    expect(getAnimatedCommandAtTime(commandModel, 500)).toMatchObject({
      arg2: 140,
      value: 160,
    });
  });

  it("supports the initial easing set", () => {
    expect(applyEasing(0.5, "linear")).toBe(0.5);
    expect(applyEasing(0.5, "ease-in")).toBe(0.25);
    expect(applyEasing(0.5, "ease-out")).toBe(0.75);
    expect(applyEasing(0.5, "ease-in-out")).toBe(0.5);
  });
});

import { describe, expect, it, vi } from "vitest";
import { Parser } from "./parser";

const parse = (input: string) => {
  const onError = vi.fn();
  const commands = new Parser(input).parse(onError);
  return { commands, onError };
};

describe("Parser", () => {
  it("parses movement, turn, and stroke-width numbers", () => {
    const { commands, onError } = parse(
      "fd -12.5 bk 4 tl 90 tr 45 setsw .5",
    );

    expect(commands.map(({ name, value }) => ({ name, value }))).toEqual([
      { name: "fd", value: -12.5 },
      { name: "bk", value: 4 },
      { name: "tl", value: 90 },
      { name: "tr", value: 45 },
      { name: "setsw", value: 0.5 },
    ]);
    expect(onError).not.toHaveBeenCalled();
  });

  it("parses an explicit animated forward range", () => {
    const { commands, onError } = parse(
      "fd anim[20 200 1200 linear] tr 90 fd 30",
    );

    expect(commands).toMatchObject([
      {
        animation: {
          cycles: 1,
          durationMs: 1200,
          easing: "linear",
          finish: 200,
          mode: "once",
          property: "value",
          start: 20,
        },
        name: "fd",
        value: 200,
      },
      { name: "tr", value: 90 },
      { name: "fd", value: 30 },
    ]);
    expect(onError).not.toHaveBeenCalled();
  });

  it("parses animated forward ranges inside repeat blocks", () => {
    const { commands, onError } = parse(
      "repeat 2 [fd anim[0 120 500 ease-out] tr 90]",
    );

    expect(commands).toMatchObject([
      {
        commands: [
          {
            animation: {
              cycles: 1,
              durationMs: 500,
              easing: "ease-out",
              finish: 120,
              mode: "once",
              property: "value",
              start: 0,
            },
            name: "fd",
            value: 120,
          },
          { name: "tr", value: 90 },
        ],
        name: "repeat",
        value: 2,
      },
    ]);
    expect(onError).not.toHaveBeenCalled();
  });

  it("parses animated ranges for one-number commands", () => {
    const { commands, onError } = parse(
      "tr anim[0 360 900 linear repeat 2] circle anim[20 120 700 ease-out pingpong 3] setsw anim[2 24 500 ease-in-out] gradientbg 020617 172554 anim[0 180 1200 linear]",
    );

    expect(commands).toMatchObject([
      {
        animation: {
          cycles: 2,
          finish: 360,
          mode: "repeat",
          property: "value",
          start: 0,
        },
        name: "tr",
        value: 360,
